from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent (FIN-12)."""
    value = Decimal(str(amount)) * Decimal(str(rate))
    return float(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

from src.invoice import tax


def test_invoice_tax():
    # Finance policy FIN-12: tax is rounded half up to the cent.
    assert tax(112.50, 0.09) == 10.13


def test_invoice_tax_rounds_half_up():
    # Decimal conversion avoids binary floating-point errors at half-cent ties.
    assert tax(100.50, 0.01) == 1.01


def test_invoice_tax_rounds_below_half_down():
    assert tax(100.40, 0.01) == 1.00


def test_invoice_tax_rounds_above_half_up():
    assert tax(100.60, 0.01) == 1.01

